//! Stats for every NPC type, transcribed from `NPC.SetDefaults` in the 1.4.5.7 build.
//!
//! The game assigns these in a long `if (type == N)` chain, and this table was extracted from it,
//! so the numbers are the game's own rather than remembered ones.
//!
//! **There is no generator for this file, and `just regen` does not touch it.** It is not on
//! AGENTS.md rule 7's list for that reason. Unlike `npc_drops.rs` or `recipes.rs`, a correction
//! here is made in place, by hand, with the `NPC.cs` line it comes from cited at the entry. Said
//! plainly because the word "generated" used to sit in this paragraph, and a reader who believed
//! it would either refuse to fix a wrong number or expect a regeneration to preserve their fix.
//!
//! **`just check-npc-data` is what stands in for one.** Rule 7's protection is not the generator
//! itself, it is that a table cannot drift from source without somebody seeing a diff; that
//! checker re-reads `SetDefaults`' own chain and compares all 691 entries on all 16 fields, and
//! it runs from `just check-data` beside the drop and recipe checkers. Every entry here was
//! verified against source that way on 2026-09-05, and the seven deliberate differences are on
//! its own record with what each stands in for.
//!
//! Five of the 691 entries deliberately do *not* match `SetDefaults`, and each one is flagged at
//! its own entry with what source really says and what depends on the difference. Both are
//! standing in for a vanilla predicate this project does not have yet:
//!
//! * `NPC.DoesntDespawnToInactivity()` (`NPC.cs:78592-78696`), which lists the four Lunar Towers
//!   alongside every worm segment and event NPC. They carry `boss: true` here only because
//!   `npc_ai::tick_life` has nothing else to ask.
//! * `NPC.isLikeATownNPC` (`NPC.cs:6880-6890`), a property that exists purely because the
//!   Skeleton Merchant is *not* `townNPC` and still needs the town-NPC behaviours.
//!
//! Checked against source in full: `boss`, `town_npc` and `friendly` were compared for all 691
//! types against a walk of `SetDefaults`' own if-chain, and these five are the only differences.

/// Number of NPC types in this build (`NPCID.Count`).
pub const NPC_COUNT: u16 = 697;

/// Everything the server needs to know about an NPC type up front.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct NpcStats {
    /// The `NPCID` constant name, for logs.
    pub name: &'static str,
    pub width: i32,
    pub height: i32,
    /// Which behaviour routine drives it.
    pub ai_style: i32,
    pub damage: i32,
    pub defense: i32,
    pub life_max: i32,
    /// 0 means immovable by knockback, 1 means fully affected.
    pub knockback_resist: f32,
    /// Copper value of the coins it drops.
    pub value: f32,
    /// How many spawn slots it takes against the cap.
    pub npc_slots: f32,
    pub no_gravity: bool,
    pub no_tile_collide: bool,
    pub friendly: bool,
    pub town_npc: bool,
    pub boss: bool,
    pub lava_immune: bool,
    pub dont_take_damage: bool,
}

